using System;using System.IO;using SynapticSea.Core.Services;using SynapticSea.Core.Systems;using SynapticSea.Core.Variant;using SynapticSea.Core.Session;
class Supplement{
static GdDict Skill(PlayerProgressionState p)=>new GdDict{{"level",p.GetSkillLevel("repair")},{"xp",p.GetSkillXp("repair")},{"fractional",p.SkillXpFractional.Get("repair",0.0)}};
static InventoryState Bag(){var b=new InventoryState();foreach(GdDict c in CatalogRegistry.LoadDict("res://data/procgen/golden/coherent_ship_001/gameplay_slice.json").GetArrayOrEmpty("loot_containers"))foreach(GdDict x in c.GetArrayOrEmpty("contents"))b.AddItem(x.GetString("item_id"),x.GetInt("qty"));return b;}
static void Main(string[] a){CoreServices.Resources=new FileSystemResourceReader(Path.Combine(a[0],"SynapticSea","Assets","StreamingAssets"));var rows=new GdArray();foreach(var c in ClassDefinition.LoadAll().Values){var p=new PlayerProgressionState();p.Configure(c,PlayerProgressionState.LoadSkillsCatalog(),PlayerProgressionState.LoadBooksCatalog());var b=Bag();var bus=new TrainingEventBus();bus.Configure();var m=new ShipSystemsManager();m.Configure(m.LoadDefinitions(),1,17);foreach(var sub in m.GetSystem("propulsion").Subcomponents)sub.Health=1;m.GetSystem("propulsion").GetSubcomponent("nav_linkage").Health=.2;var done=new GdArray();Action repair=()=>{for(int pass=0;pass<18;pass++){bool changed=false;foreach(var sid in m.SystemOrder)foreach(var sub in m.GetSystem(sid).Subcomponents){var rp=new RepairPoint();rp.Configure(sid,sub.SubcomponentId,m,b,p,Vec3.Zero,sub.RepairSeconds,sub.MinSkill);if(sub.IsFunctional()||!rp.CanBeginRepair())continue;rp.RepairCompleted+=(s,t)=>bus.Emit("repair_subcomponent",s+"."+t,p);rp.TryStart(Vec3.Zero);rp.AdvanceChannel(999);if(sub.IsFunctional()){done.Add(sid+"/"+sub.SubcomponentId);changed=true;}}if(!changed)break;}};repair();bus.Emit("repair_full_system","2",p);bus.Emit("repair_full_system","4",p);foreach(var id in new[]{"power_distribution","battery_cells","reactor_core"})m.ForceRepair("power",id);m.ForceRepair("navigation","nav_computer");var before=Skill(p);var h=new HullIntegrityState();h.Configure(CatalogRegistry.LoadDict("res://data/ship_systems/hull_compartments.json"));var sp=new BreachSealPoint();sp.Configure("cargo",h,b,p,Vec3.Zero,4,"hull_sealant",1,1.8);bool accepted=sp.TryStart(Vec3.Zero);sp.AdvanceChannel(4);var sealedXp=Skill(p);repair();rows.Add(new GdDict{{"class",c.ClassId},{"title_locked",c.Unlockable},{"before_cargo_seal",before},{"cargo_start_accepted",accepted},{"cargo_sealed",sp.Sealed},{"after_cargo_seal",sealedXp},{"after_available_repairs",Skill(p)},{"completed_repairs",done},{"repair2",p.GetSkillLevel("repair")>=2},{"remaining_bag",b.GetSummary()}});}File.WriteAllText(Path.Combine(a[1],"predeparture-supplement-model.json"),GdJson.Stringify(new GdDict{{"revision","840f14fb4450dcfba2a0bbce7cb8527e7dfa8e48"},{"scope","Fresh Core finite authored cache diagnostic, source-connected cargo seal; no natural traversal or Unity witness. No fire or hub perks granted."},{"rows",rows}}));Console.WriteLine("Supplement classes="+rows.Count);}}
